<script setup lang="ts">
import { onMounted, ref } from 'vue'

import { useCanvasStore } from '@/renderer/core/canvas/canvasStore'
import { isComponentWidget, isDOMWidget } from '@/scripts/domWidget'
import type { SimplifiedWidget } from '@/types/simplifiedWidget'

// Button widgets don't have a v-model value, they trigger actions
const props = defineProps<{
  widget: SimplifiedWidget<void>
  nodeId: string
}>()

const domEl = ref<HTMLElement>()

const { canvas } = useCanvasStore()
const widgetInstance = ref<any>(null)

onMounted(() => {
  if (!domEl.value) return
  const node = canvas?.graph?.getNodeById(props.nodeId) ?? undefined
  if (!node) return
  const widget = node.widgets?.find((w) => w.name === props.widget.name)
  if (!widget) return

  // Handle ComponentWidget (e.g., LoopNodeWidget)
  if (isComponentWidget(widget)) {
    widgetInstance.value = widget
    return
  }

  // Handle regular DOMWidget with element
  if (isDOMWidget(widget)) {
    domEl.value.replaceChildren(widget.element)
  }
})

function handleUpdateModelValue(value: any) {
  if (widgetInstance.value) {
    widgetInstance.value.value = value
    widgetInstance.value.callback?.(value)
  }
}
</script>
<template>
  <div
    v-if="widgetInstance"
    class="pointer-events-auto"
    @pointerdown.stop
    @pointermove.stop
    @pointerup.stop
  >
    <component
      :is="widgetInstance?.component"
      :model-value="widget.value"
      :widget="widgetInstance"
      v-bind="widgetInstance.props"
      @update:model-value="handleUpdateModelValue"
    />
  </div>
  <div
    v-else
    ref="domEl"
    class="pointer-events-auto"
    @pointerdown.stop
    @pointermove.stop
    @pointerup.stop
  />
</template>
